async function loadAll(ids) {
  const results = [];
  ids.forEach(async (id) => {
    const user = await fetchUser(id);
    results.push(user);
  });
  return results;
}

async function save(data) {
  try {
    return api.post('/save', data);
  } catch (err) {
    logError(err);
    return null;
  }
}

async function activeUsers(users) {
  return users.filter(async (u) => {
    const status = await getStatus(u.id);
    return status === 'active';
  });
}

